import { jsx as _jsx } from "react/jsx-runtime";
import { describe, it, expect } from "vitest";
import { screen, render } from "@testing-library/react";
import { CheckboxGroup } from "../CheckboxGroup";
import { RDSThemeProvider } from "../../../rdsThemeProvider";
import { CallistoThemeMap } from "../../../callistoTheme";
describe("CheckboxGroup", () => {
    const testIds = {
        checkboxGroup: "checkbox-group",
        checkboxes: "checkbox-group-checkboxes",
        helpText: "checkbox-group-help-text",
        label: "checkbox-group-label",
    };
    it("should render checkboxes without group label and help text", () => {
        render(_jsx(RDSThemeProvider, { themeMap: CallistoThemeMap, themeMode: "dark", children: _jsx(CheckboxGroup, { children: "checkboxes" }) }));
        expect(screen.getByTestId(testIds.checkboxes)).toHaveTextContent("checkboxes");
        expect(screen.queryByTestId(testIds.label)).not.toBeInTheDocument();
        expect(screen.queryByTestId(testIds.helpText)).not.toBeInTheDocument();
    });
    it("should apply custom test id correctly", () => {
        render(_jsx(RDSThemeProvider, { themeMap: CallistoThemeMap, themeMode: "dark", children: _jsx(CheckboxGroup, { "data-testid": "my-custom-test-id", children: "checkboxes" }) }));
        expect(screen.getByTestId("my-custom-test-id")).toHaveTextContent("checkboxes");
        expect(screen.queryByTestId(testIds.checkboxGroup)).not.toBeInTheDocument();
    });
    it("should render group label when provided", () => {
        render(_jsx(RDSThemeProvider, { themeMap: CallistoThemeMap, themeMode: "dark", children: _jsx(CheckboxGroup, { label: "checkbox-group-label", children: "checkboxes" }) }));
        expect(screen.getByTestId(testIds.checkboxes)).toHaveTextContent("checkboxes");
        expect(screen.getByTestId(testIds.label)).toHaveTextContent("checkbox-group-label");
        expect(screen.queryByTestId(testIds.helpText)).not.toBeInTheDocument();
    });
    it("should render help text when provided", () => {
        render(_jsx(RDSThemeProvider, { themeMap: CallistoThemeMap, themeMode: "dark", children: _jsx(CheckboxGroup, { helpText: "help-text", children: "checkboxes" }) }));
        expect(screen.getByTestId(testIds.checkboxes)).toHaveTextContent("checkboxes");
        expect(screen.getByTestId(testIds.helpText)).toHaveTextContent("help-text");
        expect(screen.queryByTestId(testIds.label)).not.toBeInTheDocument();
    });
    it("should render group label and help text when provided", () => {
        render(_jsx(RDSThemeProvider, { themeMap: CallistoThemeMap, themeMode: "dark", children: _jsx(CheckboxGroup, { helpText: "help-text", label: "checkbox-group-label", children: "checkboxes" }) }));
        expect(screen.getByTestId(testIds.checkboxes)).toHaveTextContent("checkboxes");
        expect(screen.getByTestId(testIds.label)).toHaveTextContent("checkbox-group-label");
        expect(screen.getByTestId(testIds.helpText)).toHaveTextContent("help-text");
    });
});
